/**
 * Analytics Dashboard JavaScript
 *
 * Core dashboard orchestration and event handlers.
 * Delegates chart rendering to DashboardChartRenderer
 * Delegates date utilities to DashboardDateUtils
 * Delegates render helpers to DashboardRenderHelpers
 *
 * @requires dashboard-date-utils.min.js
 * @requires dashboard-chart-renderer.min.js
 * @requires dashboard-render-helpers.min.js
 */

(function($) {
    'use strict';

    let loadingStateTimeout = null;
    let pendingAjaxRequests = 0;
    let currentDateLabel = '';

    const buildDateLabel = (params) => {
        if (params.start_date && params.end_date) {
            if (params.start_date === params.end_date) {
                return `(${DashboardDateUtils.formatDateLabel(params.start_date)})`;
            }
            return `(${DashboardDateUtils.formatDateLabel(params.start_date)} – ${DashboardDateUtils.formatDateLabel(params.end_date)})`;
        }
        if (params.date_range) {
            const rangeText = $('#date-range option:selected').text();
            return `(${rangeText})`;
        }
        return '';
    };

    const AnalyticsDashboard = {
        // Safe execution wrapper to avoid halting on one failure
        safe(label, fn) {
            try { fn(); } catch (e) {
                console.error('ContactIN analytics step failed:', label, e);
            }
        },
        init() {
            this.setupEventListeners();
            this.updateDateRangeDisplay();
            this.loadSummaryCards();
            this.loadInitialData();
        },

        loadSummaryCards() {
            // Load header summary card values from submissions data
            const params = this.getDateParams();
            currentDateLabel = buildDateLabel(params);
            
            pendingAjaxRequests++;
            
            // ...existing code...
            $.ajax({
                type: 'POST',
                url: contactinAnalytics.ajax_url,
                data: {
                    action: 'contactin_get_submissions_data',
                    nonce: contactinAnalytics.nonce,
                    date_range: params.date_range,
                    start_date: params.start_date,
                    end_date: params.end_date,
                    _: Date.now(),
                },
                success: (response) => {
                    if (response.success && response.data) {
                        const data = response.data;
                        if (Array.isArray(data.trend)) {
                            const total = data.trend.reduce((acc, item) => acc + (item.count || 0), 0);
                            $('#summary-submissions-7d').text(total);
                        }
                        if (data.success_rates) {
                            const emailRate = data.success_rates.email;
                            $('#summary-email-rate').text(emailRate !== null ? Math.round(emailRate) + '%' : 'N/A');
                            const crmRate = data.success_rates.crm;
                            $('#summary-crm-rate').text(crmRate !== null ? Math.round(crmRate) + '%' : 'N/A');
                        }
                        if (data.crm_counts) {
                            $('#crm-successful-count').text(data.crm_counts.successful);
                            $('#crm-failed-count').text(data.crm_counts.failed);
                            $('#crm-total-count').text(data.crm_counts.total);
                        }
                        if (typeof data.acceptance_rate !== 'undefined') {
                            const acceptanceRate = data.acceptance_rate !== null ? Math.round(data.acceptance_rate) : null;
                            $('#summary-acceptance-rate').text(acceptanceRate !== null ? acceptanceRate + '%' : 'N/A');
                        }
                        this.applyHealthColors();
                    }
                },
                error: () => {
                    $('#summary-submissions-7d').text('—');
                    $('#summary-email-rate').text('—');
                    $('#summary-crm-rate').text('—');
                    $('#summary-acceptance-rate').text('—');
                },
                complete: () => {
                    this.hideLoadingState();
                }
            });
        },

        applyHealthColors() {
            // Apply color coding to summary cards based on percentage values
            $('[data-health]').each(function() {
                const $card = $(this);
                const valueText = $card.find('.summary-value').text().trim();
                const percentage = parseFloat(valueText);
                
                if (!isNaN(percentage)) {
                    $card.removeClass('health-good health-warning health-error');
                    if (percentage >= 90) {
                        $card.addClass('health-good');
                    } else if (percentage >= 70) {
                        $card.addClass('health-warning');
                    } else {
                        $card.addClass('health-error');
                    }
                }
            });
        },

        setupEventListeners() {
            $('.tab-button').on('click', (e) => {
                this.switchTab($(e.currentTarget).data('tab'));
            });

            $('#date-range').on('change', () => {
                const value = $('#date-range').val();
                const isCustom = value === 'custom';
                this.toggleCustomDateInputs(isCustom);

                this.showLoadingState();

                const preset = DashboardDateUtils.computePresetDates(value);
                if (preset) {
                    $('#start-date').val(preset.start);
                    $('#end-date').val(preset.end);
                    this.updateDateRangeDisplay();
                    this.loadSummaryCards();
                    const activeTab = $('.tab-button.active').data('tab') || this.getTabFromHash() || 'submissions';
                    if (activeTab !== 'performance') {
                        this.loadPerformanceData();
                    }
                    this.loadTabData(activeTab);
                    return;
                }

                if (!isCustom) {
                    this.updateDateRangeDisplay();
                    this.loadSummaryCards();
                    const activeTab = $('.tab-button.active').data('tab') || this.getTabFromHash() || 'submissions';
                    if (activeTab !== 'performance') {
                        this.loadPerformanceData();
                    }
                    this.loadTabData(activeTab);
                }
            });

            $('#apply-date-range').on('click', () => {
                const start = $('#start-date').val();
                const end = $('#end-date').val();

                if (!start || !end) {
                    this.showError(contactinAnalytics.i18n.error || 'Please select both start and end dates.');
                    return;
                }

                const startDate = new Date(start);
                const endDate = new Date(end);
                if (startDate > endDate) {
                    this.showError(contactinAnalytics.i18n.error || 'Start date must be before end date.');
                    return;
                }

                this.showLoadingState();

                this.updateDateRangeDisplay();
                this.loadSummaryCards();
                const activeTab = $('.tab-button.active').data('tab') || this.getTabFromHash() || 'submissions';
                if (activeTab !== 'performance') {
                    this.loadPerformanceData();
                }
                this.loadTabData(activeTab);
            });
        },

        switchTab(tab) {
            const tabPane = $(`#${tab}-pane`);
            const tabButton = $(`#tab-${tab}`);
            if (!tabPane.length || !tabButton.length) {
                return;
            }

            $('.tab-pane').removeClass('active');
            $('.tab-button').removeClass('active');

            tabPane.addClass('active');
            tabButton.addClass('active');

            this.loadTabData(tab);
        },

        loadInitialData() {
            const hashTab = this.getTabFromHash();
            const activeTab = hashTab || $('.tab-button.active').data('tab') || 'submissions';
            this.switchTab(activeTab);

            if (activeTab !== 'performance') {
                this.loadPerformanceData();
            }
        },

        getTabFromHash() {
            const hash = window.location.hash || '';
            if (hash.startsWith('#tab-')) {
                return hash.replace('#tab-', '');
            }
            return null;
        },

        updateDateRangeDisplay() {
            const rangeValue = $('#date-range').val();
            const selectedOption = $('#date-range option:selected').text();

            const start = $('#start-date').val();
            const end = $('#end-date').val();

            if (start && end && (rangeValue === 'custom' || DashboardDateUtils.isDateBasedPreset(rangeValue))) {
                $('#date-range-display').text(`Viewing: ${DashboardDateUtils.formatDateLabel(start)} – ${DashboardDateUtils.formatDateLabel(end)}`);
                return;
            }

            $('#date-range-display').text('Viewing: ' + selectedOption);
        },

        toggleCustomDateInputs(show) {
            $('#custom-date-range').toggleClass('active', show);
        },

        getDateParams() {
            const rangeValue = $('#date-range').val() || '7';

            if (rangeValue === 'custom') {
                const start = $('#start-date').val();
                const end = $('#end-date').val();
                if (start && end) {
                    return { start_date: start, end_date: end, date_range: null };
                }
            }

            const preset = DashboardDateUtils.computePresetDates(rangeValue);
            if (preset) {
                return { start_date: preset.start, end_date: preset.end, date_range: null };
            }

            return { date_range: rangeValue, start_date: null, end_date: null };
        },

        showLoadingState() {
            if (loadingStateTimeout) {
                clearTimeout(loadingStateTimeout);
            }
            
            pendingAjaxRequests = 0;
            
            $('.summary-card .summary-value').css('opacity', '0.5');
            $('#email-delivery-rate .percentage-value').css('opacity', '0.5');
            $('#crm-sync-rate .percentage-value').css('opacity', '0.5');
            $('.queue-status-grid').css('opacity', '0.5');
            
            $('#spam-avg-score, #spam-total, #spam-flagged, #spam-percentage').css('opacity', '0.5');
            $('#email-total, #email-sent, #email-failed').css('opacity', '0.5');
            $('#crm-total, #crm-successful, #crm-failed').css('opacity', '0.5');
            
            $('#health-queue, #health-api, #system-status').css('opacity', '0.5');
        },

        hideLoadingState() {
            pendingAjaxRequests--;
            
            if (pendingAjaxRequests > 0) {
                return;
            }
            
            loadingStateTimeout = setTimeout(() => {
                $('.summary-card .summary-value').css('opacity', '1');
                $('#email-delivery-rate .percentage-value').css('opacity', '1');
                $('#crm-sync-rate .percentage-value').css('opacity', '1');
                $('.queue-status-grid').css('opacity', '1');
                
                $('#spam-avg-score, #spam-total, #spam-flagged, #spam-percentage').css('opacity', '1');
                $('#email-total, #email-sent, #email-failed').css('opacity', '1');
                $('#crm-total, #crm-successful, #crm-failed').css('opacity', '1');
                
                $('#health-queue, #health-api, #system-status').css('opacity', '1');
                
                loadingStateTimeout = null;
            }, 300);
        },

        loadTabData(tab) {
            switch (tab) {
                case 'submissions':
                    this.loadSubmissionsData();
                    break;
                case 'performance':
                    this.loadPerformanceData();
                    break;
                case 'users':
                    this.loadUsersData();
                    break;
                case 'crm':
                    this.loadCRMData();
                    break;
                case 'cron':
                    this.loadCronData();
                    break;
                default:
                    this.loadSubmissionsData();
            }
        },

        loadSubmissionsData() {
            const params = this.getDateParams();
            const dateLabel = buildDateLabel(params);
            pendingAjaxRequests++;
            
            $.ajax({
                type: 'POST',
                url: contactinAnalytics.ajax_url,
                data: {
                    action: 'contactin_get_submissions_data',
                    nonce: contactinAnalytics.nonce,
                    date_range: params.date_range,
                    start_date: params.start_date,
                    end_date: params.end_date,
                    _: Date.now(),
                },
                success: (response) => {
                    if (response.success) {
                        this.renderSubmissionsData(response.data);
                        $('.submissions-date-label').text(dateLabel);
                    } else {
                        this.showError(response.data?.message || contactinAnalytics.i18n.error);
                    }
                },
                error: () => {
                    this.showError(contactinAnalytics.i18n.error);
                },
                complete: () => {
                    this.hideLoadingState();
                },
            });
        },

        renderSubmissionsData(data) {
            if (data.status) {
                $('#status-completed').text(data.status.completed || 0);
                $('#status-pending').text(data.status.pending || 0);
                $('#status-failed').text(data.status.failed || 0);
            }

            if (data.success_rates) {
                const emailRate = data.success_rates.email !== null ? Math.round(data.success_rates.email) : null;
                const crmRate = data.success_rates.crm !== null ? Math.round(data.success_rates.crm) : null;
                
                $('#rate-email').text(emailRate !== null ? `${emailRate}%` : 'N/A');
                $('#rate-crm').text(crmRate !== null ? `${crmRate}%` : 'N/A');
            }

            if (typeof data.spam_blocked !== 'undefined') {
                $('#metric-spam-blocked').text(data.spam_blocked || 0);
            }

            if (data.rejection_reasons) {
                $('#rejection-recaptcha').text(data.rejection_reasons.recaptcha_failed || 0);
                $('#rejection-validation').text(data.rejection_reasons.validation_failed || 0);
                $('#rejection-ratelimit').text(data.rejection_reasons.rate_limited || 0);
                $('#rejection-nonce').text(data.rejection_reasons.nonce_failed || 0);
            }

            if (Array.isArray(data.trend)) {
                const total = data.trend.reduce((acc, item) => acc + (item.count || 0), 0);
                $('#summary-submissions').text(total);
                DashboardChartRenderer.renderTrendChart(data.trend);
            }
        },

        loadPerformanceData() {
            // If free version, use hardcoded placeholder data
            if (contactinAnalytics.is_free) {
                const placeholderData = {
                    queue: {
                        status: 'healthy',
                        message: 'Queue Healthy',
                        pending: 0,
                        dlq: 0,
                        failed: 0
                    },
                    email_delivery: {
                        rate: 0,
                        meta: {
                            sent: 0,
                            failed: 0,
                            total: 0
                        },
                        recent_failures: []
                    },
                    spam_intel: {
                        recaptcha_avg: 0,
                        total_submissions: 0,
                        spam_caught: 0,
                        spam_percentage: 0
                    },
                    api_performance: {
                        uptime_percent: 0,
                        avg_latency_ms: 0,
                        requests_24h: 0,
                        errors_24h: 0
                    }
                };
                this.renderPerformanceData(placeholderData);
                return;
            }
            
            const params = this.getDateParams();
            currentDateLabel = buildDateLabel(params);
            pendingAjaxRequests++;
            
            $.ajax({
                type: 'POST',
                url: contactinAnalytics.ajax_url,
                data: {
                    action: 'contactin_get_performance_data',
                    nonce: contactinAnalytics.nonce,
                    date_range: params.date_range,
                    start_date: params.start_date,
                    end_date: params.end_date,
                },
                success: (response) => {
                    if (response.success) {
                        this.renderPerformanceData(response.data);
                        this.loadQueueStats(params);
                    } else {
                        this.showError(response.data?.message || contactinAnalytics.i18n.error);
                    }
                },
                error: () => {
                    this.showError(contactinAnalytics.i18n.error);
                },
                complete: () => {
                    this.hideLoadingState();
                    this.loadHealthMetrics();
                },
            });
        },

        loadQueueStats(params) {
            pendingAjaxRequests++;
            
            $.ajax({
                type: 'POST',
                url: contactinAnalytics.ajax_url,
                data: {
                    action: 'contactin_get_queue_stats',
                    nonce: contactinAnalytics.nonce,
                    date_range: params.date_range,
                    start_date: params.start_date,
                    end_date: params.end_date,
                },
                success: (response) => {
                    if (response.success) {
                        DashboardRenderHelpers.renderQueueStats(response.data);
                    }
                },
                error: () => {
                    // Queue stats are less critical, fail silently
                },
                complete: () => {
                    this.hideLoadingState();
                },
            });
        },

        renderPerformanceData(data) {
            if (data.queue) {
                const queueStatus = DashboardRenderHelpers.getHealthStatus(data.queue.status);
                $('#health-queue').html(
                    `<div class="status-dot ${queueStatus}"></div>` +
                    `<span class="status-text">${data.queue.message || 'Queue Healthy'}</span>`
                );
                $('#queue-pending').text(data.queue.pending || 0);
                $('#queue-failed').text(data.queue.dlq || data.queue.failed || 0);
                $('#summary-queue').text(queueStatus.charAt(0).toUpperCase() + queueStatus.slice(1));
            }

            if (data.email_delivery) {
                const email = data.email_delivery;
                const rate = parseFloat(email.rate || 0) || 0;
                const sent = email.meta?.sent ?? email.sent ?? 0;
                const failed = email.meta?.failed ?? email.failed ?? 0;
                const total = email.meta?.total ?? email.total ?? sent + failed;
                const rateClass = rate >= 90 ? 'good' : rate >= 75 ? 'medium' : 'bad';
                $('#summary-email').text(`${rate.toFixed(0)}%`);
                $('#email-delivery-rate .percentage-value')
                    .text(`${rate.toFixed(1)}%`)
                    .removeClass('good medium bad')
                    .addClass(rateClass);
                $('#email-sent').text(sent);
                $('#email-failed').text(failed);
                $('#email-total').text(total);
                $('#performance-email-date-label').text(currentDateLabel);
            }

            if (data.api_stats) {
                const api = data.api_stats;
                const errorRate = parseFloat(api.error_rate || 0) || 0;
                const apiStatus = errorRate < 5 ? 'good' : errorRate < 10 ? 'warning' : 'error';
                $('#health-api').html(
                    `<div class="status-dot ${apiStatus}"></div>` +
                    `<span class="status-text">${contactinAnalytics.i18n.performance_tab || 'Performance'}: ${errorRate.toFixed(1)}% error rate</span>`
                );
                $('#api-requests').text(api.total_requests || 0);
                $('#api-errors').text(api.total_errors || 0);
                $('#performance-api-date-label').text(currentDateLabel);
            }

            if (data.crm_sync) {
                const crm = data.crm_sync;
                const rate = parseFloat(crm.rate || 0) || 0;
                const rateClass = rate >= 90 ? 'good' : rate >= 75 ? 'warning' : 'error';
                $('#crm-sync-rate .percentage-value')
                    .text(`${rate.toFixed(1)}%`)
                    .removeClass('good medium bad warning error')
                    .addClass(rateClass === 'warning' ? 'medium' : rateClass);
            }

            if (data.system_status) {
                const statusKey = data.system_status === 'good' ? 'good' : data.system_status === 'warning' ? 'warning' : 'error';
                const messages = {
                    good: 'All Systems Operational',
                    warning: 'Some Issues Detected',
                    error: 'Critical Issues Detected',
                };

                $('#system-status').html(
                    `<div class="status-dot ${statusKey}"></div>` +
                    `<span class="status-text">${messages[statusKey] || 'Status Unknown'}</span>`
                );

                const issues = [];
                if (data.queue && data.queue.status && data.queue.status !== 'good') {
                    const queueStatusKey = DashboardRenderHelpers.getHealthStatus(data.queue.status);
                    const queueAlertCopy = queueStatusKey === 'error'
                        ? 'Queue failures detected. Review the Processing Queue card.'
                        : 'Backlog detected. Review the Processing Queue card.';
                    issues.push({ component: 'Processing Queue', status: queueStatusKey, message: queueAlertCopy });
                }
                if (data.email_delivery) {
                    const rate = parseFloat(data.email_delivery.rate || 0) || 0;
                    const level = rate >= 90 ? 'good' : rate >= 75 ? 'warning' : 'error';
                    if (level !== 'good') {
                        const emailAlertCopy = level === 'error'
                            ? 'Delivery disruptions detected. Review the Email Delivery card.'
                            : 'Delivery rate trending low. Review the Email Delivery card.';
                        issues.push({ component: 'Email Delivery', status: level, message: emailAlertCopy });
                    }
                }
                if (data.api_stats) {
                    const er = parseFloat(data.api_stats.error_rate || 0) || 0;
                    const level = er < 5 ? 'good' : er < 10 ? 'warning' : 'error';
                    if (level !== 'good') {
                        const apiAlertCopy = level === 'error'
                            ? 'API outage risk detected. Review the API Availability card.'
                            : 'API errors rising. Review the API Availability card.';
                        issues.push({ component: 'API', status: level, message: apiAlertCopy });
                    }
                }
                if (data.crm_sync) {
                    const rate = parseFloat(data.crm_sync.rate || 0) || 0;
                    const level = rate >= 90 ? 'good' : rate >= 75 ? 'warning' : 'error';
                    if (level !== 'good') {
                        const crmAlertCopy = level === 'error'
                            ? 'CRM sync failures detected. Review the Salesforce CRM card.'
                            : 'CRM sync success below target. Review the Salesforce CRM card.';
                        issues.push({ component: 'CRM Sync', status: level, message: crmAlertCopy });
                    }
                }

                if (issues.length > 0) {
                    const issuesHtml = issues
                        .map((issue) => `<li><span class="status-dot ${issue.status}"></span> <strong>${issue.component}:</strong> ${issue.message || ''}</li>`)
                        .join('');
                    $('#system-status-details .status-issues-list').html(issuesHtml);
                    $('#system-status-details').show();
                } else {
                    $('#system-status-details').hide();
                }
                $('#performance-system-date-label').text(currentDateLabel);
            }
            
            // Update queue status date label
            $('#queue-status-date-label').text(currentDateLabel);
        },

        loadHealthMetrics() {
            const params = this.getDateParams();
            let days = 30;
            if (params.date_range && !isNaN(parseInt(params.date_range))) {
                days = parseInt(params.date_range);
            } else if (params.start_date && params.end_date) {
                const start = new Date(params.start_date);
                const end = new Date(params.end_date);
                days = Math.ceil((end - start) / (1000 * 60 * 60 * 24)) + 1;
            }

            pendingAjaxRequests++;
            
            $.ajax({
                type: 'POST',
                url: contactinAnalytics.ajax_url,
                data: {
                    action: 'contactin_get_health_metrics',
                    nonce: contactinAnalytics.nonce,
                    days: days,
                },
                success: (response) => {
                    if (response.success) {
                        this.renderHealthMetrics(response.data);
                    }
                },
                error: () => {
                    // Optional: log silently to avoid noisy admin UI
                },
                complete: () => {
                    this.hideLoadingState();
                },
            });
        },

        renderHealthMetrics(data) {
            if (data.email_health) {
                const email = data.email_health;
                const rateClass = email.success_rate >= 90 ? 'good' : email.success_rate >= 75 ? 'medium' : 'bad';
                $('#email-delivery-rate .percentage-value')
                    .text(`${(email.success_rate ?? 0).toFixed(1)}%`)
                    .removeClass('good medium bad')
                    .addClass(rateClass);
                $('#email-total').text(email.total ?? 0);
                $('#email-sent').text(email.sent ?? 0);
                $('#email-failed').text(email.failed ?? 0);

                const emailFailuresList = $('#email-failures');
                const suppressFailures = (email.success_rate ?? 0) >= 95 || (email.failed ?? 0) === 0;
                if (!suppressFailures && email.top_failures && email.top_failures.length > 0) {
                    emailFailuresList.empty();
                    email.top_failures.forEach((failure) => {
                        emailFailuresList.append(`<li>${failure.reason} <span class="failure-count">(${failure.count})</span></li>`);
                    });
                } else {
                    emailFailuresList.html('<li>No failures recorded</li>');
                }
            }

            if (data.crm_health) {
                const crm = data.crm_health;
                const rateClass = crm.success_rate >= 90 ? 'good' : crm.success_rate >= 75 ? 'medium' : 'bad';
                $('#crm-sync-rate .percentage-value')
                    .text(`${(crm.success_rate ?? 0).toFixed(1)}%`)
                    .removeClass('good medium bad')
                    .addClass(rateClass);
                $('#crm-total').text(crm.total ?? 0);
                $('#crm-successful').text(crm.successful ?? 0);
                $('#crm-failed').text(crm.failed ?? 0);

                const crmFailuresList = $('#crm-failures');
                const suppressCRMFailures = (crm.success_rate ?? 0) >= 95 || (crm.failed ?? 0) === 0;
                if (!suppressCRMFailures && crm.top_failures && crm.top_failures.length > 0) {
                    crmFailuresList.empty();
                    crm.top_failures.forEach((failure) => {
                        crmFailuresList.append(`<li>${failure.reason} <span class="failure-count">(${failure.count})</span></li>`);
                    });
                } else {
                    crmFailuresList.html('<li>No failures recorded</li>');
                }
            }

            if (data.spam_intelligence) {
                const spam = data.spam_intelligence;
                const scoreClass = spam.avg_score >= 0.75 ? 'good' : spam.avg_score >= 0.5 ? 'medium' : 'bad';
                $('#spam-avg-score')
                    .text((spam.avg_score ?? 0).toFixed(2))
                    .removeClass('good medium bad')
                    .addClass(scoreClass);
                $('#spam-total').text(spam.total ?? 0);
                $('#spam-flagged').text(spam.spam_count ?? 0);
                $('#spam-percentage').text(`${(spam.spam_percentage ?? 0).toFixed(1)}%`);
                $('#performance-spam-date-label').text(currentDateLabel);
            }
        },

        loadUsersData() {
            // If free version, use hardcoded placeholder data
            if (contactinAnalytics.is_free) {
                const placeholderData = {
                    device_distribution: {},
                    geographic_distribution: {},
                    traffic_sources: {},
                    browser_distribution: {}
                };
                this.renderUsersData(placeholderData);
                return;
            }
            
            const params = this.getDateParams();
            pendingAjaxRequests++;
            
            $.ajax({
                type: 'POST',
                url: contactinAnalytics.ajax_url,
                data: {
                    action: 'contactin_get_users_data',
                    nonce: contactinAnalytics.nonce,
                    date_range: params.date_range,
                    start_date: params.start_date,
                    end_date: params.end_date,
                },
                success: (response) => {
                    if (response.success) {
                        this.renderUsersData(response.data);
                    } else {
                        this.showError(response.data?.message || contactinAnalytics.i18n.error);
                    }
                },
                error: (xhr, status, error) => {
                    console.error('loadUsersData - AJAX error:', error, xhr);
                    this.showError(contactinAnalytics.i18n.error);
                },
                complete: () => {
                    this.hideLoadingState();
                },
            });
        },

        renderUsersData(data) {
            const noDataMsg = 'No data available for the selected date range. Try selecting "Last Month" or "Last 30 Days".';

            if (data.device_distribution && Object.keys(data.device_distribution).length > 0) {
                $('#chart-device-distribution').parent().show();
                $('#legend-device').html('');
                DashboardChartRenderer.renderDeviceChart(data.device_distribution);
            } else {
                DashboardChartRenderer.destroyChart('device');
                $('#chart-device-distribution').parent().hide();
                $('#legend-device').html(`<p class="placeholder-text">${noDataMsg}</p>`);
            }

            if (data.geographic_distribution && Object.keys(data.geographic_distribution).length > 0) {
                $('#chart-geographic-distribution').parent().show();
                $('#legend-geographic').html('');
                DashboardChartRenderer.renderGeographicChart(data.geographic_distribution);
            } else {
                DashboardChartRenderer.destroyChart('geographic');
                $('#chart-geographic-distribution').parent().hide();
                $('#legend-geographic').html(`<p class="placeholder-text">${noDataMsg}</p>`);
            }

            if (data.traffic_sources && Object.keys(data.traffic_sources).length > 0) {
                $('#chart-traffic-sources').parent().show();
                $('#legend-sources').html('');
                DashboardChartRenderer.renderSourcesChart(data.traffic_sources);
            } else {
                DashboardChartRenderer.destroyChart('sources');
                $('#chart-traffic-sources').parent().hide();
                $('#legend-sources').html(`<p class="placeholder-text">${noDataMsg}</p>`);
            }

            if (data.browser_distribution && Object.keys(data.browser_distribution).length > 0) {
                $('#chart-browser-distribution').parent().show();
                $('#legend-browser').html('');
                DashboardChartRenderer.renderBrowserChart(data.browser_distribution);
            } else {
                DashboardChartRenderer.destroyChart('browser');
                $('#chart-browser-distribution').parent().hide();
                $('#legend-browser').html(`<p class="placeholder-text">${noDataMsg}</p>`);
            }
        },

        loadCRMData() {
            const params = this.getDateParams();
            
            pendingAjaxRequests++;
            
            // Update date range labels for CRM tab
            this.updateCRMDateLabels(params);
            
            $.ajax({
                type: 'POST',
                url: contactinAnalytics.ajax_url,
                data: {
                    action: 'contactin_get_crm_data',
                    nonce: contactinAnalytics.nonce,
                    date_range: params.date_range,
                    start_date: params.start_date,
                    end_date: params.end_date,
                },
                success: (response) => {
                    if (!response.success) {
                        console.error('ContactIN CRM analytics: data request failed', response);
                        $('#crm-health').html('<div class="status-dot error"></div><span class="status-text">Error: ' + (response.data?.message || 'Failed to load CRM data') + '</span>');
                        $('#crm-endpoints').html('<p class="placeholder-text">Unable to load endpoint data</p>');
                        $('#chart-crm-daily-stats').parent().hide().after('<p class="placeholder-text" id="crm-chart-placeholder">Unable to load chart data</p>');
                        return;
                    }

                    const crm = response.data || {};
                    const stats = crm.statistics || {};
                    const health = crm.health || {};
                    const endpoints = crm.endpoints || [];
                    let dailyStats = crm.daily_stats || [];

                    const totalRequests = Number(stats.total_requests ?? stats.total_syncs ?? 0) || 0;
                    const successfulRequests = Number(
                        stats.successful_requests ?? stats.successful ?? 0
                    ) || 0;
                    const failedRequests = Number(
                        stats.failed_requests ?? stats.failed ?? 0
                    ) || 0;
                    const pendingRequests = Number(
                        stats.pending_requests ?? stats.pending ?? Math.max(totalRequests - successfulRequests - failedRequests, 0)
                    ) || 0;
                    const attemptedRequests = successfulRequests + failedRequests;
                    const derivedRate = attemptedRequests > 0
                        ? (successfulRequests / attemptedRequests) * 100
                        : 0;
                    const rawRate = typeof stats.success_rate !== 'undefined'
                        ? Number(stats.success_rate)
                        : null;
                    const successRate = Number.isFinite(rawRate) ? rawRate : derivedRate;

                    $('#crm-total-synced').text(totalRequests);
                    $('#crm-success-count').text(successfulRequests);
                    $('#crm-failed-count').text(failedRequests);
                    $('#crm-pending-count').text(pendingRequests);
                    $('#crm-success-rate').text(`${successRate.toFixed(1)}%`);

                    const healthStatus = health.status || 'error';
                    $('#crm-health').html(
                        `<div class="status-dot ${healthStatus}"></div>` +
                        `<span class="status-text">${health.message || 'Checking...'}</span>`
                    );
                    $('#crm-auth-status').text(health.is_authorized ? 'Connected' : 'Not Connected');

                    DashboardRenderHelpers.renderCRMEndpoints(endpoints);

                    // Remove any existing placeholder before handling chart
                    $('#crm-chart-placeholder').remove();
                    
                    // Fallback: synthesize single-day chart data if range is a single day and no daily stats are returned
                    const isSingleDay = (params.start_date && params.end_date && params.start_date === params.end_date) || (params.date_range === 'today');
                    if (dailyStats.length === 0 && isSingleDay) {
                        const dateLabel = params.start_date ? DashboardDateUtils.formatDateLabel(params.start_date) : DashboardDateUtils.formatDateLabel(new Date().toISOString().slice(0, 10));
                        const successful = (typeof stats.successful_requests !== 'undefined') ? stats.successful_requests : (stats.successful || 0);
                        const failed = (typeof stats.failed_requests !== 'undefined') ? stats.failed_requests : (stats.failed || 0);
                        dailyStats = [{ date: dateLabel, count: successful || 0, failed: failed || 0 }];
                    }

                    if (dailyStats.length > 0) {
                        // Ensure canvas has height to avoid zero-height rendering issues
                        $('#chart-crm-daily-stats').attr('height', 220);
                        $('#chart-crm-daily-stats').parent().show();
                        DashboardChartRenderer.renderCRMDailyChart(dailyStats);
                    } else {
                        DashboardChartRenderer.destroyChart('crm-daily');
                        $('#chart-crm-daily-stats').parent().hide().after('<p class="placeholder-text" id="crm-chart-placeholder">No sync activity data available for the selected date range</p>');
                    }

                    this.loadCRMActivity();
                },
                error: (xhr, status, error) => {
                    console.error('ContactIN CRM analytics: AJAX error', {xhr, status, error, responseText: xhr.responseText});
                    $('#crm-health').html('<div class="status-dot error"></div><span class="status-text">Error loading data</span>');
                    $('#crm-endpoints').html('<p class="placeholder-text">Failed to load endpoint data</p>');
                    $('#crm-activity-log').html('<p class="placeholder-text">Failed to load activity data</p>');
                    $('#chart-crm-daily-stats').parent().hide().after('<p class="placeholder-text" id="crm-chart-placeholder">Failed to load chart data</p>');
                },
                complete: () => {
                    this.hideLoadingState();
                },
            });
        },

        loadCRMActivity() {
            pendingAjaxRequests++;
            
            $.ajax({
                type: 'POST',
                url: contactinAnalytics.ajax_url,
                data: {
                    action: 'ci_get_crm_logs',
                    nonce: contactinAnalytics.crm_nonce || contactinAnalytics.nonce,
                    page: 1,
                    per_page: 5,
                    operation: 'sync',
                },
                success: (response) => {
                    if (response.success && response.data.logs) {
                        DashboardRenderHelpers.renderCRMActivityLog(response.data.logs);
                    } else {
                        $('#crm-activity-log').html('<p class="placeholder-text">No recent activity available</p>');
                    }
                },
                error: (xhr, status, error) => {
                    console.error('ContactIN CRM analytics: activity load error', {xhr, status, error, responseText: xhr.responseText});
                    $('#crm-activity-log').html('<p class="placeholder-text">Failed to load recent activity</p>');
                },
                complete: () => {
                    this.hideLoadingState();
                },
            });
        },

        loadCronData() {
            // If free version, use hardcoded placeholder data
            if (contactinAnalytics.is_free) {
                const placeholderData = {
                    statistics: {
                        health: 0,
                        executions_24h: 0,
                        failed_in_24h: 0,
                        avg_duration_ms: 0
                    },
                    status: {
                        'contactinbox_process_email_queue': {
                            health: 0,
                            last_run: null,
                            last_duration_ms: 0,
                            next_run: null
                        },
                        'contactinbox_process_crm_queue': {
                            health: 0,
                            last_run: null,
                            last_duration_ms: 0,
                            next_run: null
                        },
                        'contactinbox_cleanup_cron': {
                            health: 0,
                            last_run: null,
                            last_duration_ms: 0,
                            next_run: null
                        },
                        'contactinbox_gdpr_expiry_check': {
                            health: 0,
                            last_run: null,
                            last_duration_ms: 0,
                            next_run: null
                        },
                        'contactin_daily_analytics_aggregation': {
                            health: 0,
                            last_run: null,
                            last_duration_ms: 0,
                            next_run: null
                        }
                    }
                };
                this.renderCronData(placeholderData);
                return;
            }
            
            pendingAjaxRequests++;
            
            $.ajax({
                type: 'POST',
                url: contactinAnalytics.ajax_url,
                data: {
                    action: 'contactin_get_cron_status',
                    nonce: contactinAnalytics.nonce,
                },
                success: (response) => {
                    if (response.success) {
                        this.renderCronData(response.data);
                    } else {
                        this.showError(response.data?.message || contactinAnalytics.i18n.error);
                    }
                },
                error: () => {
                    this.showError(contactinAnalytics.i18n.error);
                },
                complete: () => {
                    this.hideLoadingState();
                },
            });
        },

        renderCronData(data) {
            const stats = data.statistics || {};
            $('#cron-health-overall').text(typeof stats.health !== 'undefined' ? `${stats.health}%` : '—');
            $('#cron-executions-24h').text(stats.executions_24h ?? 0);
            $('#cron-failed-24h').text(stats.failed_in_24h ?? 0);
            $('#cron-avg-duration').text(DashboardDateUtils.formatDuration(stats.avg_duration_ms));

            const hooks = data.status || {};
            const order = [
                'contactinbox_process_email_queue',
                'contactinbox_process_crm_queue',
                'contactinbox_cleanup_cron',
                'contactinbox_gdpr_expiry_check',
                'contactin_daily_analytics_aggregation',
            ];

            order.forEach((hook) => {
                DashboardRenderHelpers.updateCronCard(hook, hooks[hook]);
            });

            const tbody = $('#cron-events-table tbody');
            if (!hooks || Object.keys(hooks).length === 0) {
                tbody.html('<tr><td colspan="5">No records available for the past 24 hours.</td></tr>');
                return;
            }

            const rows = order
                .map((hook) => {
                    const row = hooks[hook] || {};
                    return (
                        `<tr>` +
                        `<td>${DashboardRenderHelpers.formatCronName(hook)}</td>` +
                        `<td>${DashboardRenderHelpers.getHealthLabel(row.health)}</td>` +
                        `<td>${DashboardDateUtils.formatDate(row.last_run)}</td>` +
                        `<td>${DashboardDateUtils.formatDuration(row.last_duration_ms)}</td>` +
                        `<td>${DashboardDateUtils.formatDate(row.next_run)}</td>` +
                        `</tr>`
                    );
                })
                .join('');

            tbody.html(rows);
        },

        updateCRMDateLabels(params) {
            let dateLabel = '';
            
            if (params.start_date && params.end_date) {
                // If start and end are the same, show single date
                if (params.start_date === params.end_date) {
                    dateLabel = `(${DashboardDateUtils.formatDateLabel(params.start_date)})`;
                } else {
                    dateLabel = `(${DashboardDateUtils.formatDateLabel(params.start_date)} – ${DashboardDateUtils.formatDateLabel(params.end_date)})`;
                }
            } else if (params.date_range) {
                const rangeText = $('#date-range option:selected').text();
                dateLabel = `(${rangeText})`;
            }
            
            $('#crm-stats-date-label').text(dateLabel);
            $('#crm-chart-date-label').text(dateLabel);
            $('#crm-endpoints-date-label').text(dateLabel);
        },

        showError(message) {
            const notice = $(
                `<div class="notice notice-error is-dismissible"><p>${message}</p></div>`
            );
            $('.wrap').prepend(notice);
            notice.find('.notice-dismiss').on('click', () => notice.remove());
        },
    };

    $(document).ready(() => {
        if (typeof contactinAnalytics !== 'undefined') {
            AnalyticsDashboard.init();
        }
    });
})(jQuery);
